+        this.closeButton = this.modalElement.querySelector('.modal-close-btn');
+        
+        this.initializeEventListeners();
+    }
+
+    initializeEventListeners() {
+        // Open modal when trigger buttons are clicked
+        this.triggerButtons.forEach(button => {
+            button.addEventListener('click', () => this.openModal());
+        });
+
+        // Handle action buttons in the modal
+        this.actionButtons.forEach(button => {
+            button.addEventListener('click', (e) => {
+                const action = e.target.dataset.action;
+                if (action === 'confirm') {
+                    this.handleDelete();
+                } else if (action === 'cancel') {
+                    this.closeModal();
+                }
+            });
+        });
+
+        // Close button
+        if (this.closeButton) {
+            this.closeButton.addEventListener('click', () => this.closeModal());
+        }
+
+        // Close modal when clicking on the overlay background
+        this.modalElement.addEventListener('click', (e) => {
+            if (e.target === this.modalElement) {
+                this.closeModal();
+            }
+        });
+
+        // Keyboard support: ESC to close
+        document.addEventListener('keydown', (e) => {
+            if (e.key === 'Escape' && this.modalElement.classList.contains('open')) {
+                this.closeModal();
+            }
+        });
+    }
+
+    openModal() {
+        this.modalElement.classList.add('open');
+        this.modalElement.setAttribute('aria-hidden', 'false');
+        
+        // Focus the confirm button for better keyboard navigation
+        const confirmButton = this.modalElement.querySelector('[data-action="confirm"]');
+        if (confirmButton) {
+            confirmButton.focus();
+        }
+    }
+
+    closeModal() {
+        this.modalElement.classList.remove('open');
+        this.modalElement.setAttribute('aria-hidden', 'true');
+        
+        // Return focus to the trigger button
+        const triggerButton = document.querySelector('.trigger');
+        if (triggerButton) {
+            triggerButton.focus();
+        }
